import{_ as t,o as e,c as l,a3 as i}from"./chunks/framework.bvEHUNtb.js";const u=JSON.parse('{"title":"体用生克篇之四：十应","description":"统合体用、衰旺、动静与向背，建立多维判断的基本秩序。","frontmatter":{"title":"体用生克篇之四：十应","description":"统合体用、衰旺、动静与向背，建立多维判断的基本秩序。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md","lastUpdated":1786982540000}'),n={name:"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md"};function r(s,a,o,d,h,p){return e(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占" tabindex="-1">【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占 <a class="header-anchor" href="#【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占" aria-label="Permalink to &quot;【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占&quot;">​</a></h1><blockquote><p>本篇是全书理论体系的收官。前几篇分别讲了体用、十八占、三要，这篇把三者融为一体，说清楚它们之间的关系，并补充了衰旺、内外、动静、向背、静占五个重要概念。</p></blockquote><hr><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="十应奥论" tabindex="-1">十应奥论 <a class="header-anchor" href="#十应奥论" aria-label="Permalink to &quot;十应奥论&quot;">​</a></h3><p>十应固出于三要，而妙乎三要。但以耳目所得，如见吉兆而终须吉，若逢凶谶不免乎凶，理之自然也。然以此而遇吉凶，亦有未然者也。黄金白银，为世之宝，三要得之，必以为祥。十应之决，遇金有不吉者，利刃锐兵，世谓凶器，三要得之，亦以为凶；十应之说，遇兵刃反有吉者。又若占产见少男，三要得之为生子之喜，十应见少男则凶。占病遇棺，三要占之必死；十应以为有生意。例多若此，是占卜物者，不可无应也。</p><h3 id="十应目论" tabindex="-1">十应目论 <a class="header-anchor" href="#十应目论" aria-label="Permalink to &quot;十应目论&quot;">​</a></h3><p>十应并以体卦为主，诸用卦为用。每以内分外体，用卦参观为妙。内卦不吉而外卦又吉，可以解其不吉；内卦吉而外卦不吉，反破其吉。若内外卦全吉，则断然吉。全凶则断然凶。其内吉外凶，内凶外吉，又须详理以断吉凶，慎不可胶柱鼓瑟也。外卦十应之目，则有天时、地理及写字等，其十一类之应，并以体卦为主，而随其所应以为用也。</p><h3 id="复明天时之应" tabindex="-1">复明天时之应 <a class="header-anchor" href="#复明天时之应" aria-label="Permalink to &quot;复明天时之应&quot;">​</a></h3><p>如天无云翳，明朗之际，为干之时。干、兑为体，则比和而吉；坎为体，则逢生而大吉。坤、艮为体，则泄气。震、巽为体，则见克而不吉矣。晴霁日中，为离之时，坤、兑为体则吉。雨雪为坎之时，震、巽为体则吉，离为体则不吉。雷风为震、巽之时，离为体则吉，坤、艮为体则不吉。此天时之应也。</p><h3 id="复明地理之应" tabindex="-1">复明地理之应 <a class="header-anchor" href="#复明地理之应" aria-label="Permalink to &quot;复明地理之应&quot;">​</a></h3><p>茂树秀竹，为震之地。离与震、巽为体则吉，坤、艮为体则凶。江湖、河池、川泽、溪涧为坎之地，震、巽与坎为体则吉，而离为体则不吉。窑灶之地为离，坤、艮并离为体则吉，而干、兑为体则不吉。岩穴之地为艮、干、兑与艮为体则吉，坎为体则不吉。此地理之应也。</p><h3 id="复明人事之应" tabindex="-1">复明人事之应 <a class="header-anchor" href="#复明人事之应" aria-label="Permalink to &quot;复明人事之应&quot;">​</a></h3><p>人事有论卦象五行者，有不论卦象五行者。论卦象，则老人属干，老妇属坤，艮为少男，兑为少女之类。五行生克，比和之理，与前天时、地理之卦同断。其不分卦象五行者，则以人事之纷，了见杂出，有吉有凶，此应则随其吉凶而为之兆也。又观其事则亦为某人。此人事之应也。</p><h3 id="复明时令之应" tabindex="-1">复明时令之应 <a class="header-anchor" href="#复明时令之应" aria-label="Permalink to &quot;复明时令之应&quot;">​</a></h3><p>时令不必论卦象，但详其令，月日值之五行衰旺之气。旺者，如寅卯之月日则木旺，巳午之月日火旺，申酉之月日金旺，亥子之月日水旺，辰戌丑未之月日土旺。衰者，如木旺则土衰，土旺则水衰，水旺火衰，火旺则金衰，金旺则木衰。是故生体卦气，宜值时之旺气，不宜衰气。如克体卦气，则宜乘衰。此时令之应也。</p><h3 id="复明方卦之应" tabindex="-1">复明方卦之应 <a class="header-anchor" href="#复明方卦之应" aria-label="Permalink to &quot;复明方卦之应&quot;">​</a></h3><p>即分方之卦。如离南、坎北、震东、兑西、巽东南、干西北、艮东北、坤西南类也。论吉凶者，看来占之人在何卦位，而以用卦参详。如坎为用卦，宜在坎与震、巽之位，在离则不吉。离为用卦，宜在离与坤、艮之位，在干、兑二位则不吉矣。盖宜在本卦之方，为用卦生之方，不宜受用卦克也。若夫气在之卦所在之方，又当审之。如水从坎来，为坎卦气旺。水从坤、艮来，则坎之卦气衰。火从南来，为离卦气旺，如从北来，则离之卦气衰。余皆仿此。大抵本卦之方，生为旺，受克为衰。宜以体卦参之。生体卦气，宜受旺方；克体卦气，宜受克方。此方卦之应也。又震、巽之方，不论坤、艮。坤、艮之方不论坎。坎方不论离。离方不论干。干、兑之方，不论震、巽。以其寓卦受方卦之克也。</p><h3 id="复明动物之应" tabindex="-1">复明动物之应 <a class="header-anchor" href="#复明动物之应" aria-label="Permalink to &quot;复明动物之应&quot;">​</a></h3><p>动物有论卦象者。干为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊，又螺蚌龟鳖为离之象，鱼类为坎之属，此动物之卦，以体详与。又不论卦象五行者，如乌鸦报灾，灵鹊报喜，渔雁主有书信，蛇虫防有毒害，鸡唱为家音，马嘶为动意。此动物之应也。</p><h3 id="复明静物之应" tabindex="-1">复明静物之应 <a class="header-anchor" href="#复明静物之应" aria-label="Permalink to &quot;复明静物之应&quot;">​</a></h3><p>器物之类，有论卦象者。如水属坎，火属离，水之气属震、巽，金之气属干、兑，土之气属坤、艮，为体卦，要参详。其不分卦象者，但观其器物之兆，如物之圆者，事成；器之缺者，事败。又详其器物是何物，如笔砚主文书之事，袍笏主官职之事，樽俎之具有宴集，枷锁之具防官灾。百端不一，审其物器。此静物之应也。</p><h3 id="复明言语之应" tabindex="-1">复明言语之应 <a class="header-anchor" href="#复明言语之应" aria-label="Permalink to &quot;复明言语之应&quot;">​</a></h3><p>闻人言语，不论卦象，但详其所言之事绪而占卜之。应闻吉语则吉，闻凶语则凶，若闻闹丛言语喧集，难以决断。若定人少之处，或言语可辨其事绪，则审其所言何事，心领而意会之。如说朝廷迁选，可以求名；论江湖州郡，主出行；言争讼之事，主官司；言喜庆之事，利婚姻。事绪不一，随所闻以依之。此言语之应也。</p><h3 id="复明声音之应" tabindex="-1">复明声音之应 <a class="header-anchor" href="#复明声音之应" aria-label="Permalink to &quot;复明声音之应&quot;">​</a></h3><p>耳所闻之声音而论卦象，则雷为震，风声为巽，雨声为坎，水声为坎，鼓拍槌拆之声出于木者，皆属震、巽，钟声、铃铙之声出于金者，皆属干、兑。此声音之论卦象。若为体，参详决之，如闻声音有欢笑之声，主有喜；悲愁之声，主有忧；歌唱之声，主快乐；怒号之声，主争喧。至若物声，则鸦声报灾，鹊声传喜，鸿雁声主远信，鸡凫之声为佳音。此类推声音之应也。</p><h3 id="复明五色之应" tabindex="-1">复明五色之应 <a class="header-anchor" href="#复明五色之应" aria-label="Permalink to &quot;复明五色之应&quot;">​</a></h3><p>五色不论卦象，但以所见之色推五行。青碧绿色属木，红紫赤色属火，白属金，黑属水，黄属土。外应之五行，详于内卦。体用生克、比和，吉凶可见。此五色之应也。</p><h3 id="复明写字之应" tabindex="-1">复明写字之应 <a class="header-anchor" href="#复明写字之应" aria-label="Permalink to &quot;复明写字之应&quot;">​</a></h3><p>淡中浓墨名为淬，浓墨中间薄似云，点画误书名鬼笔，定知贼在暗中缠。涕为流泪防丧服，定主忧惊梦里眠。鬼笔误书防窃盗，定知方位与通传。此写字之应验也。</p><h3 id="遗论" tabindex="-1">遗论 <a class="header-anchor" href="#遗论" aria-label="Permalink to &quot;遗论&quot;">​</a></h3><p>万物卦数，本由于《易》。今观此书，止用五行生克之理。十应三要之诀，例不同《易》，何也？盖未有《易》书，先有《易》理。《易》书作于四圣之后，《易》理着于四圣之先。人心皆有《易》理，则于《易》也，占卜无所用卦，卦即《易》也。若得《易》卦爻，观其爻辞，以断吉凶悔吝，更为妙也，未尝不用《易》。又观寓物卦数，起例之篇，止用内卦，不用外卦，何也？盖泛泛起卦之诀，十应为传授之诀。若观梅例曰「今日观梅得革，知女折花，有伤股」，明日观梅得革，亦谓女子折花，可乎？占牡丹例曰：「今日算牡丹为马践毁」，异日算牡丹亦为马所践，可乎？是必明其理。又于地风升卦，无饮食之兆而知有人相请。此要外应诀之。</p><h3 id="体用" tabindex="-1">体用 <a class="header-anchor" href="#体用" aria-label="Permalink to &quot;体用&quot;">​</a></h3><p>凡占卜成卦，即画成三重：本卦、互卦、变卦也。使于本卦分体用，此一体一用也。以卦五行明生克比和之理，此一用卦。最切看互卦变卦，互变亦用也。此内之体用也。又次看应卦，亦用也。此合内外之体用也。然则不止一体一用，所谓体一用百也。生克即分体用，则论生克。生体则吉，克体则凶，比和则吉，不必论矣。生体多者则愈吉，克体多者则愈凶。然此卦生体，诸卦有克此卦者，彼灭其吉。此卦克体，诸卦又有克此卦者，稍解其穷。有生此卦者吉，有克此卦者凶。此体用之生克，然卦之生克，有不论体用者。如占天时，有震则有雷，有巽则有风，逢坎则有雨，逢离则晴。此一定之理。又有不然者，如论卦中干、兑多，则震无雷，巽亦无风，又必有此诀也，皆隐然外卦之意。如观梅有女折花，算牡丹有马践，地风升有饮食兆。此又非外应之兆不能决也。</p><h3 id="体用论" tabindex="-1">体用论 <a class="header-anchor" href="#体用论" aria-label="Permalink to &quot;体用论&quot;">​</a></h3><p>心易寓物之用，以体为主。然人如一体一用之常，不知一体百用之变。并体之变，全卦为内，卦内亦不知一用，而互变皆用也。三要十应之卦，外卦也，外亦不一，无非用也。学寓物者，得体用以为至术，十应则罕有之，后则三要以为全术。且谓体用自体用，三要自三要，遂以体用决吉凶，以三要为吉凶之兆。孰知三要、十应、体用之致？呜乎！体用不可无三要，十应不可无体用。体用、三要、十应，理无间然也。如此者，是谓心易之全术，而可以尽占卜之道也。又如干、兑多则巽无风；坤、艮多则坎无雨；坎多，则离亦不晴。盖以干、兑之金，克震、巽之木；坤、艮之土，克坎水；坎水克离火也。此又须通变而推验之。又若占饮食，有坎则有酒，有兑则有食。如遇坤、艮，则坎亦无酒，离值则兑亦无食。余皆可以类推。故举此二类，为心易生克之例耳。</p><h3 id="衰旺论" tabindex="-1">衰旺论 <a class="header-anchor" href="#衰旺论" aria-label="Permalink to &quot;衰旺论&quot;">​</a></h3><p>既明生克，当看衰旺。旺者，如春震、巽木，夏离火，秋干、兑金，冬坎水，四季之月坤、艮土是也。衰者，如春坤、艮，夏干、兑，秋震、巽，冬离，四季之月坎是也。凡占卜，体卦宜盛旺。气旺而又逢生则吉，重遇克则凶。若体衰而逢克，则其凶甚矣。体衰而有生体之卦，则衰稍解。大抵体之卦宜旺，生体之卦气亦宜旺，克体之卦气宜衰。此心易论衰旺之诀也。</p><h3 id="内外论" tabindex="-1">内外论 <a class="header-anchor" href="#内外论" aria-label="Permalink to &quot;内外论&quot;">​</a></h3><p>凡占卜，体用为内，诸应卦为外卦，此占卜之例也。诸应卦与三要之应，与十应之应，必合内外卦而断之也。苟不知合内外卦为断，谓体用自体用，三要十应自三要十应，如此则鲜见其有验者。然十应罕有知者，如前「奥论」云：金银为世宝，三要为吉者，若震、巽为体，则金克木，反为不吉。兵刃为世凶，三要为凶者，若坎为体，则金生水，反为不凶。占产见男子，谓有生子兆，设坎为体，少男为艮土，土克水，产反不吉。占疾见棺必死，若遇离体，则木生火而反吉。似此之类，则内卦不可无外卦，外卦不可无内卦。占卜之精者，无非合内外之道也。</p><h3 id="动静" tabindex="-1">动静 <a class="header-anchor" href="#动静" aria-label="Permalink to &quot;动静&quot;">​</a></h3><p>凡占决，虽明动静之机，然有理之常，有事之变。阳动而阴静，一动一静者，理之常；此静而彼动，一静百动者，事之变也。天下之事物，纷纷群动。我则以一静而待之。事物之动，各有其端，我则以一静而测之。不动不占，不因事不占。占卜之际，察其群物之事，物动而凶者，兆吾卦之凶；物动而吉者，兆吾卦之吉。然于闹喧市缠之地，人物杂扰，群物满前，何事拓何物为吉？吾占卜之应，此又推乎理而合其事。盖于群动之中，或观其身临吾耳目之近者，可以先见者，或以群事分明者，或吾之一念所在者，此发占之所用。若求名，则于群动之中，或于官府，或有文书及袍笏仪卫之物，则为得官之应。若占讼事，而忽逢笞杖枷锁之具，则讼终不吉。占病而不见衰麻棺椁之物者，病当无恙。凡此，所谓事事相关，物物相应，是以验吾占卦之切要也。至若坐则应迟，行则应速，走则愈速，卧则愈迟，此则察其动之端也。吾心本静，人来占卜，起念以应之，即动也。以此动而测彼动，于此之念而求彼之验，诚而神知之。知此者，可以知动静之机矣。</p><h3 id="向背" tabindex="-1">向背 <a class="header-anchor" href="#向背" aria-label="Permalink to &quot;向背&quot;">​</a></h3><p>凡占卜求应，必须审其向背。向者，为事物之应，相向而来。背者，谓事物之应，相背而去也。如鸦报灾，鸦飞适来，其灾将至；鸦飞而去，则灾已过去也。如鹊报喜，鹊飞适来，其喜将至；鹊飞已去，则喜已过去也。至于外应之卦皆然。其克体之卦，器物方来，其祸将至，去则祸散。其生体之卦，器物方来则吉，去则吉已过矣。其它应兆皆然。此为占卦向背至当理也。</p><h3 id="静占" tabindex="-1">静占 <a class="header-anchor" href="#静占" aria-label="Permalink to &quot;静占&quot;">​</a></h3><p>凡占在静室，无所闻见，则无外卦，即不论外卦。但以全卦年月日值五行衰旺之气，以体用决之。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>凶谶</td><td>xiōng chèn</td><td>凶险的预兆</td></tr><tr><td>胶柱鼓瑟</td><td>jiāo zhù gǔ sè</td><td>固执不知变通，典出《史记》，胶住琴柱则音不可调</td></tr><tr><td>云翳</td><td>yún yì</td><td>云层遮蔽，翳：遮蔽</td></tr><tr><td>晴霁</td><td>qíng jì</td><td>雨后天晴</td></tr><tr><td>铃铙</td><td>líng náo</td><td>铃与铙，金属打击乐器</td></tr><tr><td>淬</td><td>cuì</td><td>此处指墨色浓淡不均</td></tr><tr><td>鬼笔</td><td>—</td><td>书写时笔画有误，如鬼画符</td></tr><tr><td>袍笏</td><td>páo hù</td><td>官服与朝笏，代指官职</td></tr><tr><td>樽俎</td><td>zūn zǔ</td><td>酒器与食器，代指宴席</td></tr><tr><td>衰麻棺椁</td><td>—</td><td>丧服（衰麻）与棺材，代指丧事</td></tr><tr><td>笞杖枷锁</td><td>chī zhàng jiā suǒ</td><td>刑具，代指官讼刑罚</td></tr><tr><td>四圣</td><td>—</td><td>伏羲、文王、周公、孔子，《易》之四圣</td></tr><tr><td>鸡凫</td><td>jī fú</td><td>鸡与野鸭</td></tr><tr><td>理无间然</td><td>—</td><td>道理之间没有间隙，完全融通</td></tr><tr><td>体一用百</td><td>—</td><td>体只有一个，用却有百种</td></tr></tbody></table><hr><h2 id="📖-白话译文摘要" tabindex="-1">📖 白话译文摘要 <a class="header-anchor" href="#📖-白话译文摘要" aria-label="Permalink to &quot;📖 白话译文摘要&quot;">​</a></h2><h3 id="十应奥论-1" tabindex="-1">十应奥论 <a class="header-anchor" href="#十应奥论-1" aria-label="Permalink to &quot;十应奥论&quot;">​</a></h3><p>十应出于三要，但比三要更精妙。三要只凭耳目所得，见吉则吉，见凶则凶，是表层判断。十应则要结合内卦（体用）来修正——黄金白银三要以为吉，但若震巽为体，金克木则反凶；兵刃三要以为凶，但若坎为体，金生水则反吉。占产见少男三要以为喜，但少男为艮土克坎水（体），则反凶。占病见棺三要以为死，但若离为体，木生火则反有生意。<strong>外应必须与内卦结合，才能得出正确判断。</strong></p><h3 id="十应目论-1" tabindex="-1">十应目论 <a class="header-anchor" href="#十应目论-1" aria-label="Permalink to &quot;十应目论&quot;">​</a></h3><p>十应以体卦为主，外应卦为用。内外卦合参：内外俱吉则大吉，内外俱凶则大凶，一吉一凶则详审，不可胶柱鼓瑟。外卦十一类应：天时·地理·人事·时令·方卦·动物·静物·言语·声音·五色·写字。</p><h3 id="十一类应-天时至写字" tabindex="-1">十一类应（天时至写字） <a class="header-anchor" href="#十一类应-天时至写字" aria-label="Permalink to &quot;十一类应（天时至写字）&quot;">​</a></h3><p>每类的核心逻辑：外应所属五行，与体卦五行做生克比和判断。</p><ul><li>天时：晴（乾）、雨（坎）、雷风（震巽）、日中（离）→ 与体卦生克</li><li>地理：茂树（震）、江湖（坎）、窑灶（离）、岩穴（艮）→ 与体卦生克</li><li>人事：论卦象者（老人乾·少男艮·少女兑）做生克；不论卦象者随吉凶直取</li><li>时令：不论卦象，直接看月日五行旺衰，生体之卦气宜旺，克体之卦气宜衰</li><li>方卦：来占之人所在方位，与用卦生克参详</li><li>动物：论卦象者（乾马·坤牛·震龙·巽鸡·坎豕·离雉·艮狗·兑羊）做生克；不论卦象者直取象意</li><li>静物：论卦象者做生克；不论卦象者直取器物象意（圆成缺败·笔砚文书·枷锁官灾）</li><li>言语：不论卦象，直取所言事绪（迁选求名·争讼主官司·喜庆利婚姻）</li><li>声音：论卦象者（雷震·风巽·雨坎·金乾兑）做生克；不论卦象者取声音吉凶（笑喜·悲忧·怒争）</li><li>五色：不论卦象，以色推五行，与内卦体用生克</li><li>写字：墨色浓淡·笔画有误，各有特定应验</li></ul><h3 id="遗论-1" tabindex="-1">遗论 <a class="header-anchor" href="#遗论-1" aria-label="Permalink to &quot;遗论&quot;">​</a></h3><p>易理先于易书。起卦之诀（内卦）是基础，十应是传授之诀（外卦）。两者缺一不可——内卦无外卦不能决断（如地风升无饮食兆而知有人相请），外卦无内卦则误判（如金银三要为吉而十应反凶）。</p><h3 id="体用-1" tabindex="-1">体用 <a class="header-anchor" href="#体用-1" aria-label="Permalink to &quot;体用&quot;">​</a></h3><p><strong>体一用百</strong>：体只有一个，用却有百种。</p><ul><li>内之用：本卦用卦·互卦·变卦</li><li>外之用：十一类应卦</li><li>生体多则愈吉，克体多则愈凶</li><li>生体之卦被克，则吉被灭；克体之卦被克，则凶稍解</li></ul><h3 id="体用论-1" tabindex="-1">体用论 <a class="header-anchor" href="#体用论-1" aria-label="Permalink to &quot;体用论&quot;">​</a></h3><p>体用·三要·十应，<strong>理无间然</strong>，不可分割：</p><ul><li>体用不可无三要（否则无法感知外应）</li><li>十应不可无体用（否则外应无法正确解读）</li><li>三者合一，才是心易之全术</li></ul><h3 id="衰旺论-1" tabindex="-1">衰旺论 <a class="header-anchor" href="#衰旺论-1" aria-label="Permalink to &quot;衰旺论&quot;">​</a></h3><p>旺：春震巽·夏离·秋乾兑·冬坎·四季末坤艮<br> 衰：春坤艮·夏乾兑·秋震巽·冬离·四季末坎</p><ul><li>体旺逢生 → 大吉</li><li>体旺逢克 → 凶（但有一战之力）</li><li>体衰逢克 → 凶甚</li><li>体衰逢生 → 衰稍解</li><li>生体之卦气宜旺，克体之卦气宜衰</li></ul><h3 id="内外论-1" tabindex="-1">内外论 <a class="header-anchor" href="#内外论-1" aria-label="Permalink to &quot;内外论&quot;">​</a></h3><p>体用为内卦，三要十应为外卦。内外必须合参，分开则不验。内外互相制约、互相修正，<strong>占卜之精者，无非合内外之道</strong>。</p><h3 id="动静-1" tabindex="-1">动静 <a class="header-anchor" href="#动静-1" aria-label="Permalink to &quot;动静&quot;">​</a></h3><ul><li>理之常：阳动阴静，一动一静</li><li>事之变：我以一静待万动</li><li>「不动不占，不因事不占」</li><li>群动之中，取最近耳目者·最分明者·一念所在者为应</li><li>吾心本静，起念即动，以此动测彼动</li></ul><h3 id="向背-1" tabindex="-1">向背 <a class="header-anchor" href="#向背-1" aria-label="Permalink to &quot;向背&quot;">​</a></h3><p>应兆有向有背：</p><ul><li><strong>向</strong>（来）：祸福将至</li><li><strong>背</strong>（去）：祸福已过<br> 克体之物来→祸将至，去→祸已散<br> 生体之物来→吉将至，去→吉已过</li></ul><h3 id="静占-1" tabindex="-1">静占 <a class="header-anchor" href="#静占-1" aria-label="Permalink to &quot;静占&quot;">​</a></h3><p>无外应时，不论外卦，只以年月日五行衰旺配合体用决断。</p><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、十应与三要的层次关系" tabindex="-1">一、十应与三要的层次关系 <a class="header-anchor" href="#一、十应与三要的层次关系" aria-label="Permalink to &quot;一、十应与三要的层次关系&quot;">​</a></h3><p>本篇开头就点明了三要与十应的关系：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三要（耳目心感知）</span></span>
<span class="line"><span>    ↓ 出于·但妙乎</span></span>
<span class="line"><span>十应（结合内卦修正）</span></span></code></pre></div><p>三要是感知层——耳目所得，直接取象，见吉则吉，见凶则凶。<br> 十应是判断层——将感知到的外象，与内卦（体用）结合，做五行生克修正。</p><p><strong>三要给出象，十应给出判断。</strong></p><p>这就是为什么同一个外象（金银·兵刃·少男·棺），在不同的内卦下，结论完全相反。</p><h3 id="二、十一类应的两种处理方式" tabindex="-1">二、十一类应的两种处理方式 <a class="header-anchor" href="#二、十一类应的两种处理方式" aria-label="Permalink to &quot;二、十一类应的两种处理方式&quot;">​</a></h3><p>十一类应里，有一个重要的分类原则：</p><table tabindex="0"><thead><tr><th>类型</th><th>处理方式</th><th>举例</th></tr></thead><tbody><tr><td><strong>论卦象五行者</strong></td><td>外应所属卦，与体卦做生克比和</td><td>天时晴（乾）+ 坎体 → 乾生坎（金生水）→ 大吉</td></tr><tr><td><strong>不论卦象五行者</strong></td><td>直接取象意或事绪</td><td>言语说争讼 → 主官司；鸦声 → 报灾</td></tr></tbody></table><p>不是所有外应都要转化为五行再做生克，有些象直接取其意义即可。这是「推数又须明理」在十应层面的体现。</p><h3 id="三、体一用百-最完整的体用模型" tabindex="-1">三、体一用百：最完整的体用模型 <a class="header-anchor" href="#三、体一用百-最完整的体用模型" aria-label="Permalink to &quot;三、体一用百：最完整的体用模型&quot;">​</a></h3><p>「体用」这个概念，在本篇得到了最完整的展开：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体（一个）</span></span>
<span class="line"><span>├── 内之用</span></span>
<span class="line"><span>│   ├── 本卦用卦</span></span>
<span class="line"><span>│   ├── 互卦（亦用）</span></span>
<span class="line"><span>│   └── 变卦（亦用）</span></span>
<span class="line"><span>└── 外之用（十一类应卦）</span></span>
<span class="line"><span>    ├── 天时·地理·人事·时令·方卦</span></span>
<span class="line"><span>    ├── 动物·静物·言语·声音</span></span>
<span class="line"><span>    ├── 五色·写字</span></span>
<span class="line"><span>    └── ……（无穷）</span></span></code></pre></div><p>体只有一个，用却有百种。每一个外应，都是「用」的一种形式。</p><p>这个模型解释了为什么「体一用百」——不是体用关系只有一对，而是体与所有外应之间，都构成体用关系。</p><h3 id="四、衰旺论的精细化" tabindex="-1">四、衰旺论的精细化 <a class="header-anchor" href="#四、衰旺论的精细化" aria-label="Permalink to &quot;四、衰旺论的精细化&quot;">​</a></h3><p>衰旺论在这里做了一个重要的精细化，不只是「体旺则吉，体衰则凶」，而是：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体旺 + 逢生 → 大吉</span></span>
<span class="line"><span>体旺 + 逢克 → 凶（有抵抗力）</span></span>
<span class="line"><span>体衰 + 逢生 → 衰稍解（有救）</span></span>
<span class="line"><span>体衰 + 逢克 → 凶甚（无救）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>生体之卦气宜旺（生的力量要强）</span></span>
<span class="line"><span>克体之卦气宜衰（克的力量要弱）</span></span></code></pre></div><p>这是一个<strong>力量对比</strong>的模型，不只看单一关系，要看双方的力量强弱。</p><h3 id="五、动静-一静待万动" tabindex="-1">五、动静：一静待万动 <a class="header-anchor" href="#五、动静-一静待万动" aria-label="Permalink to &quot;五、动静：一静待万动&quot;">​</a></h3><p>动静这一节，是全书最有哲学深度的段落之一：</p><blockquote><p>「天下之事物，纷纷群动。我则以一静而待之。」</p></blockquote><p>这不是消极的等待，是主动的感知姿态。万物在动，我以静心来感应它们的动——这与三要序里「方寸湛然，灵台皎洁」是同一个状态。</p><blockquote><p>「吾心本静，人来占卜，起念以应之，即动也。以此动而测彼动。」</p></blockquote><p>占卜的那一刻，心从静转动——这个「动」，就是感通的发生。用自己心的动，来感测外部事物的动。</p><p>群动之中如何取应？三个原则：</p><ol><li><strong>最近耳目者</strong>——最先进入感知的</li><li><strong>最分明者</strong>——最清晰的</li><li><strong>一念所在者</strong>——心最先注意到的</li></ol><h3 id="六、向背-时间维度的应验" tabindex="-1">六、向背：时间维度的应验 <a class="header-anchor" href="#六、向背-时间维度的应验" aria-label="Permalink to &quot;六、向背：时间维度的应验&quot;">​</a></h3><p>向背是一个很实用的概念，解决了「应验已过还是将至」的问题：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应兆向我而来 → 事将发生</span></span>
<span class="line"><span>应兆背我而去 → 事已过去</span></span></code></pre></div><p>这个原则让克应从「有没有」变成了「什么时候」——不只判断吉凶，还判断时间节点。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="内外之道-镜中镜" tabindex="-1">内外之道：镜中镜 <a class="header-anchor" href="#内外之道-镜中镜" aria-label="Permalink to &quot;内外之道：镜中镜&quot;">​</a></h3><p>内外论说：「占卜之精者，无非合内外之道也。」</p><p>内卦是我对事情的判断框架，外卦是宇宙对这个判断的回应。两者不是独立的，是互相印证、互相修正的。</p><p>这让我想到一个意象：<strong>镜中镜</strong>。</p><p>内卦是一面镜子，照见事情的象。外应是另一面镜子，照见内卦的象。两面镜子相对，无穷深远。</p><p>占卜的精妙，不在于哪一面镜子更准，而在于<strong>让两面镜子对齐</strong>——内外一致，则断然；内外相悖，则存疑详审。</p><h3 id="一静待万动" tabindex="-1">一静待万动 <a class="header-anchor" href="#一静待万动" aria-label="Permalink to &quot;一静待万动&quot;">​</a></h3><p>「我则以一静而待之」——这句话读起来很平静，但背后是极大的定力。</p><p>万物在动，人心最容易被动所牵。被牵了，就跟着动，就乱了，就看不清了。</p><p>一静，不是不动，是<strong>有根的静</strong>。根在，才能感应万动而不乱。</p><p>这与三要序「方寸湛然」、与序「心致而目玩」，都是同一种状态的不同描述。</p><h3 id="向背-时间是有方向的" tabindex="-1">向背：时间是有方向的 <a class="header-anchor" href="#向背-时间是有方向的" aria-label="Permalink to &quot;向背：时间是有方向的&quot;">​</a></h3><p>向背这一节，让我感受到：<strong>时间是有方向的，象也是有方向的</strong>。</p><p>同一只乌鸦，飞来和飞去，意义完全不同。不是象变了，是象的方向变了。</p><p>这提醒我们：看象，不只看「是什么象」，还要看「象在往哪里走」。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>十应出于三要，妙乎三要：三要感知，十应判断，层次不同</li><li>十一类应：天时·地理·人事·时令·方卦·动物·静物·言语·声音·五色·写字</li><li>两种处理：论卦象五行者做生克，不论卦象者直取象意</li><li>体一用百：体一个，内外之用无穷</li><li>体用·三要·十应，理无间然，不可分割</li><li>衰旺精细化：体旺逢生大吉，体衰逢克凶甚，生体之气宜旺，克体之气宜衰</li><li>内外论：内外必合参，分开则不验</li><li>动静：一静待万动，以此动测彼动</li><li>向背：来则将至，去则已过</li><li>静占：无外应则只论内卦体用与年月日衰旺</li></ul><p><strong>规律提炼</strong></p><ol><li>三要·十应·体用三者是一个整体，不可割裂——这是本篇最核心的论断</li><li>外应必须与内卦结合才能正确解读，单独的外应可能误导</li><li>衰旺不只是「旺则吉衰则凶」，要看生克双方的力量强弱对比</li><li>群动之中取应：最近·最分明·一念所在，三者优先</li><li>向背判断时间：来则将至，去则已过</li><li>静占是简化版：无外应时，只用内卦体用 + 年月日衰旺</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之一「体用总诀」→ 此篇「体一用百」：体用概念的完整展开</li><li>篇之三「三要灵应」→ 此篇「十应奥论」：三要是感知，十应是判断，层次递进</li><li>篇之一「要在圆机，不可执」→ 此篇「慎不可胶柱鼓瑟」：同一精神</li><li>篇之二「克应」→ 此篇十一类应：克应的完整分类展开</li><li>序「心致而目玩」→ 此篇「一静待万动」：同一种感知状态</li></ul><p><strong>词条更新</strong></p><table tabindex="0"><thead><tr><th>词条</th><th>简释</th></tr></thead><tbody><tr><td>十应</td><td>十一类外应：天时·地理·人事·时令·方卦·动物·静物·言语·声音·五色·写字，与内卦体用合参</td></tr><tr><td>体一用百</td><td>体只有一个，内外之用无穷，每一外应皆为用</td></tr><tr><td>内外论</td><td>体用为内，三要十应为外，内外必合参，分开则不验</td></tr><tr><td>向背</td><td>应兆向来则事将至，背去则事已过</td></tr><tr><td>静占</td><td>无外应时，只论内卦体用与年月日衰旺</td></tr></tbody></table><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-016</strong>：十应目论说「外卦十应之目，则有天时、地理及写字等，其十一类之应」——标题说「十应」，但列出的是十一类（天时·地理·人事·时令·方卦·动物·静物·言语·声音·五色·写字）。「十应」与「十一类」的数字不一致，原文未作解释。可能「十应」是约数，或某两类合并计为一应。存疑备注，待卷三「十应诀」章节核对。</p></blockquote><blockquote><p><strong>❓****-017</strong>：方卦之应中「震、巽之方，不论坤、艮。坤、艮之方不论坎。坎方不论离。离方不论干。干、兑之方，不论震、巽」——这五条「不论」的逻辑是「寓卦受方卦之克」，即被克方不论克己之方。但实际上这五条只覆盖了五组克关系中的五个方向，并非完整的十组（每组克关系有两个方向）。是否有遗漏？待卷三印证。</p></blockquote><blockquote><p><strong>❓****-018</strong>：写字之应「淡中浓墨名为淬，浓墨中间薄似云，点画误书名鬼笔，定知贼在暗中缠」——此节以韵文写成，与其他各节散文体例不同，且内容较为晦涩。「淬」「鬼笔」的具体含义及应验逻辑不甚清晰，存疑备注。</p></blockquote>`,143)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
